#!/usr/bin/env python3
"""TokenGuard - LLM API 429 Prevention Engine"""

import argparse
import json
import re
import sys
import time
from dataclasses import dataclass, field
from typing import Dict, List, Optional

DEFAULT_QUOTAS = {
    "gemini-3-flash": 1_000_000,
    "gemini-3-pro": 2_000_000,
    "claude-haiku": 50_000,
    "claude-sonnet": 200_000,
    "claude-opus": 200_000,
    "gpt-4o": 800_000,
    "deepseek": 1_000_000,
}

@dataclass
class CheckDecision:
    action: str
    estimated_tokens: int
    remaining_quota: int
    usage_pct: float
    wait_seconds: Optional[float] = None
    fallback_model: Optional[str] = None
    reason: Optional[str] = None

@dataclass
class UsageRecord:
    timestamp: float
    tokens: int

class TokenGuard:
    def __init__(self, quotas=None, deterministic_time=None):
        self.quotas = DEFAULT_QUOTAS.copy()
        if quotas:
            self.quotas.update(quotas)
        self.usage = {model: [] for model in self.quotas}
        self.total_checks = 0
        self.tokens_saved = 0
        self.blocks = 0
        self.fallbacks = 0
        self.retry_delays = {}
        self._deterministic_time = deterministic_time

    @property
    def _current_time(self):
        if self._deterministic_time is not None:
            return self._deterministic_time
        return time.time()

    def add_custom_quota(self, model, tpm_limit):
        self.quotas[model] = tpm_limit
        if model not in self.usage:
            self.usage[model] = []

    def _is_cjk(self, char):
        cp = ord(char)
        return (0x4e00 <= cp <= 0x9fff or  # CJK Unified Ideographs
                0x3400 <= cp <= 0x4dbf or  # CJK Extension A
                0x20000 <= cp <= 0x2a6df or  # CJK Extension B
                0xac00 <= cp <= 0xd7af or  # Hangul Syllables
                0x3040 <= cp <= 0x309f or  # Hiragana
                0x30a0 <= cp <= 0x30ff)  # Katakana

    def estimate_tokens(self, text):
        if not text:
            return 0
        tokens = 0
        english_chars = 0
        for char in text:
            if self._is_cjk(char):
                tokens += 1
            elif char.isalnum():
                english_chars += 1
        tokens += max(0, english_chars // 4)
        return tokens

    def _get_usage_this_minute(self, model):
        now = self._current_time
        window_start = now - 60.0
        records = self.usage.get(model, [])
        recent = [r for r in records if r.timestamp >= window_start]
        self.usage[model] = recent
        return sum(r.tokens for r in recent)

    def check(self, text, model):
        self.total_checks += 1
        if model not in self.quotas:
            return CheckDecision("block", 0, 0, 100.0, reason="Unknown model")

        estimated = self.estimate_tokens(text)
        limit = self.quotas[model]
        used = self._get_usage_this_minute(model)
        remaining = limit - used
        usage_pct = (used / limit) * 100 if limit > 0 else 100.0

        if remaining < estimated:
            self.blocks += 1
            self.tokens_saved += estimated
            return CheckDecision("block", estimated, remaining, usage_pct,
                                reason="Quota exceeded")

        if usage_pct > 95:
            return CheckDecision("block", estimated, remaining, usage_pct,
                                reason="Quota nearly exhausted")

        if usage_pct > 80:
            wait = (usage_pct - 80) * 0.5
            return CheckDecision("wait", estimated, remaining, usage_pct, wait)

        return CheckDecision("proceed", estimated, remaining, usage_pct)

    def record_usage(self, tokens, model):
        if model not in self.usage:
            self.usage[model] = []
        self.usage[model].append(UsageRecord(self._current_time, tokens))

    def record_429(self, model, retry_delay):
        self.retry_delays[model] = retry_delay

    def get_status(self):
        models_status = {}
        for model, limit in self.quotas.items():
            used = self._get_usage_this_minute(model)
            remaining = limit - used
            usage_pct = (used / limit) * 100 if limit > 0 else 100.0
            if usage_pct < 80:
                status = "OK"
            elif usage_pct < 95:
                status = "WAIT"
            else:
                status = "BLOCKED"
            models_status[model] = {
                "tpm_limit": limit,
                "used_this_minute": used,
                "remaining": remaining,
                "usage_pct": f"{usage_pct:.1f}%",
                "status": status
            }
        return {
            "models": models_status,
            "stats": {
                "total_checks": self.total_checks,
                "tokens_saved": self.tokens_saved,
                "blocks": self.blocks,
                "fallbacks": self.fallbacks
            },
            "retry_delays": self.retry_delays
        }

